select * from jsonb_populate_recordset(null::public.curated_question_catalog, $questions$[{"id":"1b83ec1e-640e-49fa-8e22-aa70847c5f7c","state":"AC","subject":"Realidade do Estado do Acre","subtopic":"Fronteiras e integração regional","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:27:31.267461+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O estado do Acre faz fronteira com Peru e Bolívia. A posição fronteiriça é relevante para integração regional e desafios de segurança pública.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:27:31.267461+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Fronteiras e integração regional","question_text":"O Acre possui fronteira internacional com:\n\nA) Colômbia e Venezuela.\nB) Peru e Bolívia.\nC) Equador e Peru.\nD) Bolívia e Paraguai.\nE) Peru e Chile.","content_status":"active","career_category":"conhecimentos jurídicos e básicos","official_answer":"B","external_item_key":"pcac-acre-fronteira-01","import_unique_key":"767b65f1bfbb7340f5ee60a9b784377ffcb84feb6ef91e1d9c21a3e31e0329d3","syllabus_topic_id":"2e09c840-dc34-4ce5-9ce4-fde39a62ce61","import_content_key":"767b65f1bfbb7340f5ee60a9b784377ffcb84feb6ef91e1d9c21a3e31e0329d3","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"45dec39a-e219-47a7-89f9-4dab48eec10f","state":"AC","subject":"Realidade do Estado do Acre","subtopic":"Chico Mendes e reservas extrativistas","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:27:31.267461+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A Reserva Extrativista é unidade de Uso Sustentável do SNUC. Protege os meios de vida e a cultura de populações extrativistas tradicionais e assegura uso sustentável, sujeito a regras e plano de manejo.","is_original":true,"legal_basis":[{"law":"Lei nº 9.985/2000","article":"arts. 14, VII, e 18"}],"verified_at":"2026-11-21T10:27:31.267461+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Chico Mendes e reservas extrativistas","question_text":"Sobre as reservas extrativistas e o movimento dos seringueiros no Acre, assinale a alternativa correta:\n\nA) RESEX é unidade de Proteção Integral que proíbe qualquer uso dos recursos.\nB) Chico Mendes defendia a substituição da floresta por pecuária extensiva.\nC) RESEX integra o grupo de Uso Sustentável e busca compatibilizar conservação com meios de vida tradicionais.\nD) Seringueiros e povos indígenas são categorias jurídicas idênticas.\nE) RESEX não possui regras de uso nem plano de manejo.","content_status":"active","career_category":"conhecimentos jurídicos e básicos","official_answer":"C","external_item_key":"pcac-acre-resex-01","import_unique_key":"07cf4c1f7394e140711d032b8f7e3f64a812717af16448b1eebd7ef7c2d7fe90","syllabus_topic_id":"2e09c840-dc34-4ce5-9ce4-fde39a62ce61","import_content_key":"07cf4c1f7394e140711d032b8f7e3f64a812717af16448b1eebd7ef7c2d7fe90","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"91dd028f-ea79-496f-b72f-149b3e1edefb","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Anulação e revogação","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:28:24.338706+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Revogação retira ato válido por conveniência e oportunidade. Anulação decorre de ilegalidade.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:28:24.338706+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Anulação e revogação","question_text":"A Administração identifica que um ato administrativo válido tornou-se inconveniente diante de nova política pública. A retirada por mérito administrativo denomina-se:\nA) anulação.\nB) cassação obrigatória.\nC) revogação.\nD) convalidação.\nE) caducidade judicial.","content_status":"active","career_category":"conhecimentos jurídicos","official_answer":"C","external_item_key":"pcac-adm-atos-01","import_unique_key":"9b8a23f9d99a9bd0281b7188df296f25e9f4391e69b70a0fb61b325092e2bcaa","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"9b8a23f9d99a9bd0281b7188df296f25e9f4391e69b70a0fb61b325092e2bcaa","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"4e6cfa9a-441f-4cf6-83f0-9bac38a331be","state":"AC","subject":"Noções de Direito Administrativo","subtopic":"Organização administrativa","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:28:24.338706+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A desconcentração distribui competências internamente, dentro da mesma pessoa jurídica, por meio de órgãos. Descentralização envolve outra pessoa.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:28:24.338706+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Organização administrativa","question_text":"A criação de departamentos dentro de uma secretaria estadual, sem criação de nova pessoa jurídica, é exemplo de:\nA) descentralização por colaboração.\nB) desconcentração administrativa.\nC) concessão de serviço público.\nD) criação de autarquia.\nE) privatização.","content_status":"active","career_category":"conhecimentos jurídicos","official_answer":"B","external_item_key":"pcac-adm-org-01","import_unique_key":"a1335105d483c5784108f2f5a7c1d853eac89100c2bd5749c9bad9108b92afa8","syllabus_topic_id":"ec1c0da0-edef-4e18-b70a-ad0bc4a88aea","import_content_key":"a1335105d483c5784108f2f5a7c1d853eac89100c2bd5749c9bad9108b92afa8","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"31f3f4cb-c370-4d12-afc2-f4d0ac4a602a","state":"AC","subject":"Noções de Direito Constitucional","subtopic":"Arts. 37 a 41 — acumulação","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:27:31.267461+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A Constituição admite dois cargos de professor, desde que haja compatibilidade de horários e observância do teto remuneratório. A regra geral continua sendo a vedação de acumulação.","is_original":true,"legal_basis":[{"law":"Constituição Federal","article":"art. 37, XVI"}],"verified_at":"2026-11-21T10:27:31.267461+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Arts. 37 a 41 — acumulação","question_text":"Servidor efetivo pretende acumular seu cargo com outro cargo público de professor. A Constituição admite essa acumulação quando:\n\nA) houver autorização do chefe imediato, independentemente de horários.\nB) houver compatibilidade de horários e respeito ao teto constitucional.\nC) o segundo cargo for temporário, ainda que incompatível.\nD) ambos os cargos forem de entes federativos diferentes, sem outro requisito.\nE) houver intervalo mínimo de seis horas entre jornadas.","content_status":"active","career_category":"conhecimentos jurídicos e básicos","official_answer":"B","external_item_key":"pcac-const-art37-01","import_unique_key":"b20e7a703c12d300629d8cb8d9a0865e0e9774ad544e2b3c16379c584fa6dfcf","syllabus_topic_id":"f03fb59a-4ba9-483b-9d33-673fed427a26","import_content_key":"b20e7a703c12d300629d8cb8d9a0865e0e9774ad544e2b3c16379c584fa6dfcf","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"b6e134fc-93f0-485b-9365-0d992d2a15c0","state":"AC","subject":"Noções de Direito Constitucional","subtopic":"Art. 5º — inviolabilidade domiciliar","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:27:31.267461+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A casa é asilo inviolável. Sem consentimento, o ingresso só cabe em flagrante delito, desastre ou para prestar socorro, a qualquer hora; por determinação judicial, durante o dia. A mera utilidade investigativa não cria exceção.","is_original":true,"legal_basis":[{"law":"Constituição Federal","article":"art. 5º, XI"}],"verified_at":"2026-11-21T10:27:31.267461+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Art. 5º — inviolabilidade domiciliar","question_text":"Em diligência investigativa, policiais ingressam em residência sem consentimento, sem mandado e sem situação de flagrante, desastre ou necessidade de socorro, alegando apenas conveniência da apuração. À luz do art. 5º, XI, da Constituição, a entrada é:\n\nA) válida, pois a investigação criminal afasta a inviolabilidade domiciliar.\nB) válida em qualquer horário quando houver fundada suspeita.\nC) inválida, pois a conveniência investigativa não constitui exceção constitucional.\nD) válida desde que a diligência seja posteriormente comunicada ao juiz.\nE) inválida apenas se o morador apresentar reclamação formal.","content_status":"active","career_category":"conhecimentos jurídicos e básicos","official_answer":"C","external_item_key":"pcac-const-art5-01","import_unique_key":"de8b0923c41065bc0012542cdbbf1938050fae39f19039587a95c438d0425f36","syllabus_topic_id":"f03fb59a-4ba9-483b-9d33-673fed427a26","import_content_key":"de8b0923c41065bc0012542cdbbf1938050fae39f19039587a95c438d0425f36","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"45be1437-133d-417a-80d5-b96616ff42f0","state":"AC","subject":"Noções de Direito Penal e Processual Penal","subtopic":"Falsidade ideológica — art. 299 do CP","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:27:31.267461+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A falsidade ideológica do art. 299 ocorre quando se omite declaração devida ou se insere/faz inserir declaração falsa ou diversa em documento, com finalidade específica prevista no tipo. A autenticidade material do documento pode permanecer intacta.","is_original":true,"legal_basis":[{"law":"Código Penal","article":"art. 299"}],"verified_at":"2026-11-21T10:27:31.267461+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Falsidade ideológica — art. 299 do CP","question_text":"Documento formalmente autêntico é preenchido com declaração falsa sobre fato juridicamente relevante, para alterar a verdade sobre fato que o documento deve provar. A conduta aponta, em tese, para:\n\nA) falsidade ideológica.\nB) uso de documento falso, necessariamente.\nC) violação de sepultura.\nD) fraude processual, em qualquer hipótese.\nE) falsa perícia.","content_status":"active","career_category":"conhecimentos jurídicos e básicos","official_answer":"A","external_item_key":"pcac-penal-falsidade-01","import_unique_key":"d7aa1a99a767ef1868e613d91cc5081b2a73abba3b7e8eaf7e86422bd71696c4","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","import_content_key":"d7aa1a99a767ef1868e613d91cc5081b2a73abba3b7e8eaf7e86422bd71696c4","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"058cd7a8-1037-41ed-9635-a4ea78ebbf74","state":"AC","subject":"Noções de Direito Penal e Processual Penal","subtopic":"Fraude processual — art. 347 do CP","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:27:31.267461+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 347 exige inovação artificiosa do estado de lugar, coisa ou pessoa e finalidade de induzir a erro juiz ou perito. O parágrafo único prevê hipótese específica em processo penal mesmo antes de iniciado.","is_original":true,"legal_basis":[{"law":"Código Penal","article":"art. 347"}],"verified_at":"2026-11-21T10:27:31.267461+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Fraude processual — art. 347 do CP","question_text":"Durante a pendência de procedimento, alguém altera artificiosamente a posição de vestígios para induzir juiz ou perito a erro. O elemento central que deve ser verificado para o art. 347 do CP é:\n\nA) mera alteração física, independentemente de finalidade.\nB) inovação artificiosa e finalidade de induzir juiz ou perito a erro.\nC) obtenção de vantagem econômica obrigatória.\nD) participação de funcionário público como sujeito ativo necessário.\nE) existência de sentença penal condenatória transitada em julgado.","content_status":"active","career_category":"conhecimentos jurídicos e básicos","official_answer":"B","external_item_key":"pcac-penal-fraude-01","import_unique_key":"a40b82c9d6d659eb733535fd9cae1bd6bdd5bde123ec3da93caf1bbe01e1b8ae","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","import_content_key":"a40b82c9d6d659eb733535fd9cae1bd6bdd5bde123ec3da93caf1bbe01e1b8ae","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null}]$questions$::jsonb)
